import ast, json, hashlib
from pathlib import Path
r=json.loads(Path('runtime.json').read_text()); p=json.loads(Path('proposal.json').read_text())
def validate(value,schema,where='"'$'"'):
 types={'object':dict,'array':list,'string':str,'boolean':bool}
 typ=schema.get('type')
 if typ in types: assert isinstance(value,types[typ]),(where,typ)
 if 'const' in schema: assert value==schema['const'],where
 if 'enum' in schema: assert value in schema['enum'],where
 if isinstance(value,dict):
  assert all(k in value for k in schema.get('required',[])),where
  if schema.get('additionalProperties') is False: assert set(value)<=set(schema.get('properties',{})),where
  for k,s in schema.get('properties',{}).items():
   if k in value: validate(value[k],s,where+'.'+k)
 if isinstance(value,list):
  assert len(value)>=schema.get('minItems',0),where
  for i,v in enumerate(value): validate(v,schema.get('items',{}),where+f'[{i}]')
 if isinstance(value,str): assert len(value)>=schema.get('minLength',0),where
validate(p['study'],r['study_schema'])
assert set(p)=={'study','parent_trial','variants'}
assert p['parent_trial'] in {x['id'] for x in r['context']['history']}
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
ref=ast.parse(Path('baseline_reference.py').read_text())
refclass=next(n for n in ref.body if isinstance(n,ast.ClassDef))
ref_forward=next(n for n in refclass.body if isinstance(n,ast.FunctionDef) and n.name=='forward')
ref_forward.name='_backbone_forward'
ref_init=next(n for n in refclass.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
for v in p['variants']:
 f=Path(v['file']); source=f.read_text(); tree=ast.parse(source); compile(tree,str(f),'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert config==v['config'],v['name']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__'}
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 forward=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='_backbone_forward')
 init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 assert ast.dump(forward)==ast.dump(ref_forward),'Backbone forward changed'
 assert all(ast.dump(x)==ast.dump(y) for x,y in zip(init.body,ref_init.body)),'Backbone construction changed'
 assert len(init.body)>len(ref_init.body)
 print(v['name'], 'syntax/API source/backbone/config checks PASS', hashlib.sha256(f.read_bytes()).hexdigest())
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
print('Proposal schema PASS; read-only reference hash unchanged. No torch execution or training performed.')
PY"

